"""Verify generated bytes against the same frozen report; this is not evidence/visual certification."""
import argparse
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re
import shutil
import subprocess
import tempfile
import zipfile
from urllib.parse import urlsplit
import xml.etree.ElementTree as ET
from generate_report import markdown_document, page_number_footer_xml
from report_schema import read_report, parse_formats, public_texts, effective_presentation, contents_entries

MAX_FILE_BYTES = 32 * 1024 * 1024


def bounded_read(path, limit=MAX_FILE_BYTES):
    if not path.is_file() or path.stat().st_size == 0 or path.stat().st_size > limit:
        raise ValueError(f'Missing, empty or oversized output: {path.name}')
    return path.read_bytes()


class PublicHTML(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ignored = 0
        self.body = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if any(key.lower().startswith('on') for key in attributes) or tag in ('iframe', 'object', 'embed'):
            raise ValueError('Executable report HTML is not allowed')
        if tag == 'script' and not (attributes.get('type') == 'application/json' and attributes.get('id') in ('sourceweft-font-evidence', 'sourceweft-font-licenses')):
            raise ValueError('Executable report HTML is not allowed')
        if tag == 'body':
            self.body = True
        if tag in ('script', 'style'):
            self.ignored += 1

    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.ignored -= 1
        if tag == 'body':
            self.body = False

    def handle_data(self, value):
        if self.body and not self.ignored:
            self.parts.append(value)


def normalized(value):
    return re.sub(r'\s+', '', value)


def assert_content(report, extracted, label, ordered=True):
    actual = normalized(extracted)
    if ordered:
        expected_all = normalized(' '.join(public_texts(report)))
        if actual != expected_all:
            raise ValueError(f'{label} full public text differs from the frozen report')
        return
    position = 0
    for expected in public_texts(report):
        value = normalized(expected)
        found = actual.find(value, position if ordered else 0)
        if found < 0:
            raise ValueError(f'{label} content differs at: {expected[:100]}')
        if ordered:
            position = found + len(value)


def xml_signature(node):
    return (node.tag, tuple(sorted(node.attrib.items())), node.text or '', node.tail or '', tuple(xml_signature(child) for child in node))


def validate_page_footer(archive, names, document, types):
    """Allow only our exact non-executable PAGE/NUMPAGES part and one live reference."""
    w = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    r = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'
    rel_ns = '{http://schemas.openxmlformats.org/package/2006/relationships}'
    footer_names = [name for name in names if name.startswith('word/footer')]
    if footer_names != ['word/footer1.xml']:
        raise ValueError('Unexpected or missing DOCX page-number footer parts')
    if any(name.startswith('word/_rels/footer') for name in names):
        raise ValueError('DOCX footer relationships are not allowed')
    data = archive.read('word/footer1.xml')
    if b'<!DOCTYPE' in data or b'<!ENTITY' in data:
        raise ValueError('Unexpected DOCX XML declarations')
    if xml_signature(ET.fromstring(data)) != xml_signature(ET.fromstring(page_number_footer_xml())):
        raise ValueError('DOCX page-number footer differs from the controlled fields')
    rel_path = 'word/_rels/document.xml.rels'
    if rel_path not in names:
        raise ValueError('Missing DOCX page-number relationship')
    rel_data = archive.read(rel_path)
    if b'<!DOCTYPE' in rel_data or b'<!ENTITY' in rel_data:
        raise ValueError('Unexpected DOCX XML declarations')
    relations = ET.fromstring(rel_data)
    if relations.tag != rel_ns + 'Relationships':
        raise ValueError('Invalid DOCX page-number relationships root')
    relationship_ids = [node.get('Id') for node in relations]
    if any(not identity for identity in relationship_ids) or len(relationship_ids) != len(set(relationship_ids)):
        raise ValueError('Duplicate or empty DOCX relationship Id')
    footer_relations = [node for node in relations if node.get('Type', '').endswith('/footer')]
    if len(footer_relations) != 1:
        raise ValueError('Unexpected DOCX page-number relationships')
    relation = footer_relations[0]
    if relation.tag != rel_ns + 'Relationship' or relation.get('Type') != 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer' or relation.get('Target') != 'footer1.xml' or relation.get('TargetMode', 'Internal') != 'Internal' or not relation.get('Id'):
        raise ValueError('Invalid DOCX page-number relationship')
    refs = list(document.iter(w + 'footerReference'))
    section_refs = [ref for section in document.iter(w + 'sectPr') for ref in section.findall(w + 'footerReference')]
    if len(refs) != 1 or len(section_refs) != 1 or refs[0] is not section_refs[0] or refs[0].attrib != {w + 'type': 'default', r + 'id': relation.get('Id')}:
        raise ValueError('Unexpected or dangling DOCX page-number reference')
    c = '{http://schemas.openxmlformats.org/package/2006/content-types}'
    footer_types = [node for node in types if 'footer' in node.get('PartName', '') or 'footer' in node.get('ContentType', '')]
    if len(footer_types) != 1 or footer_types[0].tag != c + 'Override' or footer_types[0].attrib != {'PartName': '/word/footer1.xml', 'ContentType': 'application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml'}:
        raise ValueError('Invalid DOCX page-number content type')


def pdf_body_with_page_numbers(raw, bbox):
    """Validate actual bottom-margin glyphs before removing exactly one footer per page.

    A body sentence resembling a page number is never removed by a global regex.
    We require spatial evidence plus the last raw line, independently on every page.
    """
    root = ET.fromstring(bbox)
    ns = '{http://www.w3.org/1999/xhtml}'
    pages = list(root.iter(ns + 'page'))
    chunks = raw.split('\f')
    if chunks and not chunks[-1].strip():
        chunks.pop()
    if not pages or len(pages) != len(chunks):
        raise ValueError('PDF page-count evidence differs')
    bodies = []
    for index, (page, chunk) in enumerate(zip(pages, chunks), 1):
        height = float(page.get('height', '0'))
        width = float(page.get('width', '0'))
        if not 840 < height < 843 or not 594 < width < 597:
            raise ValueError('Unexpected PDF page size for controlled footer')
        expected = f'Page {index} / {len(pages)}'
        # A4 body ends at 20 mm; the native footer is 10 mm from the edge.
        footer_words = [word for word in page.iter(ns + 'word') if float(word.get('yMin', '-1')) >= height - 58]
        if normalized(' '.join(word.text or '' for word in footer_words)) != normalized(expected):
            raise ValueError('PDF page-number footer glyphs differ or are missing')
        if any(float(word.get('xMin', '-1')) < width * .3 or float(word.get('xMax', '9999')) > width * .7 or float(word.get('yMax', '9999')) > height - 20 for word in footer_words):
            raise ValueError('PDF page-number footer is outside its controlled location')
        lines = chunk.rstrip().splitlines()
        if not lines or normalized(lines[-1]) != normalized(expected):
            raise ValueError('PDF raw footer differs from spatial page-number evidence')
        bodies.append('\n'.join(lines[:-1]))
    return '\n'.join(bodies)


def assert_pdf_navigation(report, xml, pdf_name):
    """Check exported clickable TOC links and actual heading text at their destinations.

    Poppler splits long/mixed-font labels into fragments. Consume them in report
    order rather than using a dictionary keyed by a possibly repeated heading.
    """
    def reject(reason):
        raise ValueError('PDF contents navigation: ' + reason)
    root = ET.fromstring(xml)
    pages = root.findall('page')
    numbers = [page.get('number') for page in pages]
    if not pages or numbers != [str(index) for index in range(1, len(pages) + 1)]:
        reject('invalid page sequence')
    fonts = {font.get('id'): float(font.get('size', '0')) for font in root.iter('fontspec')}
    anchors = [(int(page.get('number')), anchor) for page in pages for anchor in page.iter('a')]
    expected_file = Path(pdf_name).stem + '.html'

    def heading_on_page(page, heading):
        # The generator uses Heading 1 at 15 pt. At explicit Poppler zoom=1,
        # match only contiguous visible heading fragments, never a whole-page
        # concatenation that could falsely match ordinary prose or the TOC.
        texts = page.findall('text')
        expected = normalized(heading)
        for start, text in enumerate(texts):
            candidate = ''
            previous = None
            first_left = float(text.get('left', '0'))
            for node in texts[start:]:
                if list(node.iter('a')) or not 14.5 <= fonts.get(node.get('font'), 0) <= 15.5:
                    break
                left, top = float(node.get('left', '0')), float(node.get('top', '0'))
                if previous is not None:
                    prev_left, prev_top, prev_width, prev_height = previous
                    same_line = abs(top - prev_top) <= 2 and abs(left - (prev_left + prev_width)) <= 8
                    next_line = 0 < top - prev_top <= prev_height * 1.8 and abs(left - first_left) <= 2
                    if not (same_line or next_line):
                        break
                candidate += normalized(''.join(node.itertext()))
                if candidate == expected:
                    return True
                if not expected.startswith(candidate):
                    break
                previous = (left, top, float(node.get('width', '0')), float(node.get('height', '0')))
        return False

    cursor = 0
    previous_target = 0
    checked = []
    for _, heading in contents_entries(report):
        expected = normalized(heading)
        label = ''
        target = None
        source_pages = []
        while label != expected:
            if cursor >= len(anchors):
                reject('missing clickable internal link for ' + heading)
            source_page, anchor = anchors[cursor]
            cursor += 1
            href = urlsplit(anchor.get('href', ''))
            if href.scheme or href.netloc or href.query or href.path not in ('', expected_file) or not re.fullmatch(r'[1-9][0-9]*', href.fragment):
                reject('external or invalid target for ' + heading)
            destination = int(href.fragment)
            if not 1 <= destination <= len(pages) or (target is not None and target != destination):
                reject('missing or inconsistent destination for ' + heading)
            target = destination
            fragment = normalized(''.join(anchor.itertext()))
            if not fragment or not expected.startswith(label + fragment):
                reject('link label/order differs from the frozen report')
            label += fragment
            source_pages.append(source_page)
        if target < previous_target or target < max(source_pages) or not heading_on_page(pages[target - 1], heading):
            reject('target does not contain the actual section heading: ' + heading)
        previous_target = target
        checked.append({'heading': heading, 'sourcePages': sorted(set(source_pages)), 'targetPage': target})
    if cursor != len(anchors):
        reject('unexpected extra PDF links')
    return checked


def assert_docx_navigation(report, document, styles):
    entries = contents_entries(report)
    if not entries:
        return
    w = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    def reject(reason):
        raise ValueError('DOCX contents navigation: ' + reason)
    parents = {child: parent for parent in document.iter() for child in parent}
    links = list(document.iter(w + 'hyperlink'))
    starts = list(document.iter(w + 'bookmarkStart'))
    ends = list(document.iter(w + 'bookmarkEnd'))
    if len(links) != len(entries) or len(starts) != len(entries) or len(ends) != len(entries):
        reject('unexpected link or bookmark count')
    definitions = {node.get(w + 'styleId'): node for node in styles.findall(w + 'style')}
    for name in ('Hyperlink', 'FollowedHyperlink'):
        if name not in definitions or definitions[name].get(w + 'type') != 'character':
            reject('missing registered hyperlink character style')
    for index, (link, (_, heading), start, end) in enumerate(zip(links, entries, starts, ends), 1):
        name, identity = f'sw_section_{index}', str(index)
        if link.attrib != {w + 'anchor': name, w + 'history': '1'} or ''.join(node.text or '' for node in link.iter(w + 't')) != heading:
            reject('link label or internal target differs')
        if any(run.find(w + 'rPr/' + w + 'rStyle') is None or run.find(w + 'rPr/' + w + 'rStyle').get(w + 'val') != 'Hyperlink' for run in link.findall(w + 'r')):
            reject('link does not apply its registered character style')
        if start.attrib != {w + 'id': identity, w + 'name': name} or end.attrib != {w + 'id': identity}:
            reject('bookmark identity differs')
        paragraph = parents.get(start)
        style = paragraph.find(w + 'pPr/' + w + 'pStyle') if paragraph is not None else None
        if paragraph is None or paragraph.tag != w + 'p' or parents.get(end) is not paragraph or style is None or style.get(w + 'val') != 'Heading1' or ''.join(node.text or '' for node in paragraph.iter(w + 't')) != heading:
            reject('bookmark does not contain the actual section heading')


def docx_text(path, report=None):
    bounded_read(path)
    with zipfile.ZipFile(path) as archive:
        entries = archive.infolist()
        if len(entries) > 2000 or sum(item.file_size for item in entries) > 100 * 1024 * 1024:
            raise ValueError('DOCX archive exceeds expansion bounds')
        names = [entry.filename for entry in entries]
        if len(names) != len(set(names)):
            raise ValueError('Duplicate DOCX archive member')
        required = {'[Content_Types].xml', '_rels/.rels', 'word/document.xml'}
        if not required.issubset(names):
            raise ValueError('Missing required DOCX package parts')
        if archive.testzip() is not None:
            raise ValueError('DOCX archive CRC failed')
        def package_xml(name):
            data = archive.read(name)
            if b'<!DOCTYPE' in data or b'<!ENTITY' in data:
                raise ValueError('Unexpected DOCX XML declarations')
            return ET.fromstring(data)
        types = package_xml('[Content_Types].xml')
        content_ns = '{http://schemas.openxmlformats.org/package/2006/content-types}'
        if types.tag != content_ns + 'Types' or not any(
            entry.get('PartName') == '/word/document.xml' and
            entry.get('ContentType') == 'application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml'
            for entry in types.findall(content_ns + 'Override')
        ):
            raise ValueError('Invalid DOCX main document content type')
        relationships = package_xml('_rels/.rels')
        relation_ns = '{http://schemas.openxmlformats.org/package/2006/relationships}'
        if relationships.tag != relation_ns + 'Relationships' or not any(
            entry.get('Type') == 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument' and
            entry.get('Target') in ('word/document.xml', '/word/document.xml') and
            entry.get('TargetMode', 'Internal') == 'Internal'
            for entry in relationships.findall(relation_ns + 'Relationship')
        ):
            raise ValueError('Invalid DOCX officeDocument relationship')
        info = archive.getinfo('word/document.xml')
        if info.file_size > MAX_FILE_BYTES:
            raise ValueError('DOCX XML exceeds limit')
        xml = archive.read(info)
        if b'<!DOCTYPE' in xml or b'<!ENTITY' in xml:
            raise ValueError('Unexpected DOCX XML declarations')
        document = ET.fromstring(xml)
        if report is not None and contents_entries(report):
            if 'word/styles.xml' not in names:
                raise ValueError('DOCX contents navigation: missing style definitions')
            assert_docx_navigation(report, document, package_xml('word/styles.xml'))
        numbered = report is not None and effective_presentation(report)['pageNumbers']
        if numbered:
            validate_page_footer(archive, names, document, types)
            if any(name.startswith('word/header') for name in names):
                raise ValueError('Unexpected header parts outside the report DOCX body')
        else:
            if any(name.startswith(('word/footer', 'word/_rels/footer')) for name in names) or list(document.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}footerReference')) or any('footer' in node.get('PartName', '') or 'footer' in node.get('ContentType', '') for node in types):
                raise ValueError('Unexpected page-number parts outside the report DOCX body')
        namespace = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
        for entry in entries:
            if entry.filename.startswith(('word/header', 'word/footer', 'word/comments', 'word/footnotes', 'word/endnotes')) and entry.filename.endswith('.xml'):
                if numbered and entry.filename == 'word/footer1.xml':
                    continue
                extra = archive.read(entry)
                if b'<!DOCTYPE' in extra or b'<!ENTITY' in extra:
                    raise ValueError('Unexpected DOCX XML declarations')
                extra_root = ET.fromstring(extra)
                if any((node.text or '').strip() for node in extra_root.iter(namespace + 't')) or any(node.tag in {namespace + name for name in ('fldSimple', 'fldChar', 'instrText', 'hyperlink', 'drawing', 'object')} for node in extra_root.iter()):
                    raise ValueError('Unexpected text outside the report DOCX body')
    if b'<!DOCTYPE' in xml or b'<!ENTITY' in xml:
        raise ValueError('Unexpected DOCX XML declarations')
    root = ET.fromstring(xml)
    namespace = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    return '\n'.join(''.join(t.text or '' for t in p.iter(namespace + 't')) for p in root.iter(namespace + 'p'))


def verify(source, directory, formats):
    report = read_report(source)
    directory = Path(directory)
    # The published editing source must be the same validated semantic input.
    if read_report(directory / 'report.source.json') != report:
        raise ValueError('Private source does not match the input version')
    files = []
    checks = []
    for fmt in formats:
        path = directory / ('report.' + fmt)
        data = bounded_read(path)
        if fmt == 'html':
            parser = PublicHTML()
            parser.feed(data.decode('utf-8'))
            assert_content(report, '\n'.join(parser.parts), 'HTML')
            checks.append('HTML reading order and all public text')
        elif fmt == 'md':
            if data.decode('utf-8') != markdown_document(report):
                raise ValueError('Markdown differs from the frozen report')
            checks.append('Markdown exact deterministic text')
        elif fmt == 'docx':
            assert_content(report, docx_text(path, report), 'DOCX')
            checks.append('DOCX package and public reading order')
        else:
            if not data.startswith(b'%PDF-'):
                raise ValueError('Invalid PDF signature')
            with tempfile.TemporaryDirectory(prefix='sourceweft-report-verify-') as temporary:
                extracted = Path(temporary) / 'content.txt'
                subprocess.run(['pdftotext', '-raw', str(path.resolve()), str(extracted)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30, check=True)
                # Read PDF content streams: layout mode interleaves adjacent
                # wrapped table cells. Keep the same strict whole-fragment,
                # number and citation checks; visual layout is reviewed separately.
                public = bounded_read(extracted).decode('utf-8')
                if effective_presentation(report)['pageNumbers']:
                    bbox_path = Path(temporary) / 'spatial.html'
                    subprocess.run(['pdftotext', '-bbox', str(path.resolve()), str(bbox_path)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30, check=True)
                    public = pdf_body_with_page_numbers(public, bounded_read(bbox_path))
                assert_content(report, public, 'PDF', ordered=False)
                if contents_entries(report):
                    if not shutil.which('pdftohtml'):
                        raise RuntimeError('pdftohtml is required to verify requested PDF contents navigation; no fallback is accepted')
                    navigation = Path(temporary) / 'navigation.xml'
                    with navigation.open('wb') as stream:
                        subprocess.run(['pdftohtml', '-xml', '-stdout', '-i', '-zoom', '1', str(path.resolve())], stdout=stream, stderr=subprocess.DEVNULL, timeout=30, check=True)
                    assert_pdf_navigation(report, bounded_read(navigation), path.name)
                    checks.append('PDF clickable internal contents links and actual target headings')
            checks.append('PDF extraction and all public text/numbers; visual review remains required')
        files.append({'fileName': path.name, 'byteLength': len(data), 'contentDigest': 'sha256:' + hashlib.sha256(data).hexdigest()})
    unexpected = [f'report.{fmt}' for fmt in ('md', 'docx', 'pdf') if fmt not in formats and (directory / f'report.{fmt}').exists()]
    if unexpected:
        raise ValueError('Unrequested deliverables present: ' + ', '.join(unexpected))
    return {'passed': True, 'checks': checks, 'files': files, 'evidenceAuthenticated': False, 'visualReview': 'not_run'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True)
    parser.add_argument('--output-dir', required=True)
    parser.add_argument('--formats', default='html,md')
    args = parser.parse_args()
    print(json.dumps(verify(args.source, args.output_dir, parse_formats(args.formats)), ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
